div.script:
(function () {

function setupAssignPreview(missionId){
var sel = document.getElementById("assignSelect_" + missionId);
if(!sel) return;

var preview = document.getElementById("candPreview_" + missionId);
var img = document.getElementById("candImg_" + missionId);
var name = document.getElementById("candName_" + missionId);
var specs = document.getElementById("candSpecs_" + missionId);
var rate = document.getElementById("candRate_" + missionId);

function render(){
var opt = sel.options[sel.selectedIndex];
if(!opt || !opt.dataset || !opt.dataset.name){
if(preview) preview.style.display = "none";
return;
}
if(img) img.src = opt.dataset.img || "/web/static/img/user_menu_avatar.png";
if(name) name.textContent = opt.dataset.name || "";
if(specs) specs.textContent = opt.dataset.specs || "—";
if(rate) rate.textContent = (opt.dataset.rate || "0");
if(preview) preview.style.display = "block";
}

sel.addEventListener("change", render);
render();
}

// ✅ au chargement : initialiser tous les selects présents
document.addEventListener("DOMContentLoaded", function(){
var selects = document.querySelectorAll("select[id^='assignSelect_']");
selects.forEach(function(s){
var id = s.id.replace("assignSelect_", "");
setupAssignPreview(id);
});
});

// ✅ quand le modal bootstrap s’ouvre : refresh (au cas où)
document.addEventListener("shown.bs.modal", function(e){
if(!e.target || !e.target.id) return;
if(e.target.id.startsWith("assignModal_")){
var missionId = e.target.id.replace("assignModal_", "");
setupAssignPreview(missionId);
}
});

})();

window.abSubmitDone = function(missionId){
// optional confirm
if(!confirm("Marquer cette mission comme terminée ?")) return false;

var btn = event && event.target ? event.target : null;
var loading = document.getElementById("doneLoading_" + missionId);
if(loading) loading.style.display = "flex";
if(btn){
btn.disabled = true;
btn.innerText = "Traitement...";
}

// let the user see the animation for a short moment, then submit
setTimeout(function(){
var form = document.getElementById("doneForm_" + missionId);
if(form) form.submit();
}, 650);

return false; // prevent immediate submit
}
